function validate([plants, capacityA, capacityB]) {
  if (!Array.isArray(plants) || plants.length < 1 || plants.length > 100000) return 'plants needs 1 to 100000 values.';
  if (plants.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each plant needs an integer from 1 to 1000000.';
  let most = 0;
  for (const v of plants) if (v > most) most = v;
  for (const cap of [capacityA, capacityB]) {
    if (!Number.isInteger(cap) || cap < most || cap > 1000000000) return 'Each capacity is an integer from max(plants) to 10^9.';
  }
  return null;
}

