function minimumRefill(plants, capacityA, capacityB) {
  let left = 0;
  let right = plants.length - 1;
  let waterA = capacityA;
  let waterB = capacityB;
  let refills = 0;

  while (left < right) {
    if (waterA < plants[left]) {
      refills++;
      waterA = capacityA;
    }
    waterA -= plants[left];
    left++;
    if (waterB < plants[right]) {
      refills++;
      waterB = capacityB;
    }
    waterB -= plants[right];
    right--;
  }
  if (left === right && Math.max(waterA, waterB) < plants[left]) {
    refills++;
  }
  return refills;
}

