function minimumRefill(plants, capacityA, capacityB) {
  const n = plants.length;
  const half = Math.floor(n / 2);
  const run = (list, cap) => {
    let water = cap, count = 0;
    for (const need of list) { if (water < need) { count++; water = cap; } water -= need; }
    return [count, water];
  };
  const [countA, leftA] = run(plants.slice(0, half), capacityA);
  const [countB, leftB] = run(plants.slice(n - half).reverse(), capacityB);
  let total = countA + countB;
  if (n % 2 === 1) {
    const holder = leftA >= leftB ? leftA : leftB;
    if (holder < plants[half]) total++;
  }
  return total;
}

