function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 10);
  const top = large ? (rand() < 0.5 ? 1000000 : 1000) : (rand() < 0.2 ? 1000000 : 10);
  const plants = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const most = Math.max(...plants);
  const capacity = () => {
    const r = rand();
    if (r < 0.1) return 1000000000;
    if (r < 0.3) return most;
    return Math.min(1000000000, most + Math.floor(rand() * most * (large ? 4 : 2)));
  };
  return [plants, capacity(), capacity()];
}
